function rateLimit(timestamps, capacity, refillPerSec) {
  const out = [];
  if (timestamps.length === 0) return out;
  let tokens = capacity;
  let last = timestamps[0];
  for (const t of timestamps) {
    tokens = Math.min(capacity, tokens + ((t - last) / 1000) * refillPerSec);
    last = t;
    if (tokens >= 1) {
      tokens -= 1;
      out.push(true);
    } else {
      out.push(false);
    }
  }
  return out;
}

