solution:
function bm25(query, docs, k1, b) {
  const tok = (s) => s.toLowerCase().split(/[^a-z0-9]+/).filter(Boolean);
  const N = docs.length;
  if (N === 0) return [];
  const toks = docs.map(tok);
  const avgdl = toks.reduce((s, t) => s + t.length, 0) / N;
  if (avgdl === 0) return docs.map(() => 0);
  const q = [...new Set(tok(query))];
  return toks.map((t) => {
    let score = 0;
    for (const w of q) {
      const n = toks.filter((d) => d.includes(w)).length;
      const tf = t.filter((x) => x === w).length;
      if (tf === 0) continue;
      const idf = Math.log(1 + (N - n + 0.5) / (n + 0.5));
      score += (idf * tf * (k1 + 1)) / (tf + k1 * (1 - b + (b * t.length) / avgdl));
    }
    return Math.round(score * 1000) / 1000;
  });
}

