function mmr(rel, sim, lambda, k) {
  const n = rel.length;
  const picked = [];
  const limit = Math.min(k, n);
  while (picked.length < limit) {
    let best = -1;
    let bestScore = -Infinity;
    for (let i = 0; i < n; i++) {
      if (picked.includes(i)) continue;
      let score;
      if (picked.length === 0) score = rel[i];
      else score = lambda * rel[i] - (1 - lambda) * Math.max(...picked.map((j) => sim[i][j]));
      if (score > bestScore) { bestScore = score; best = i; }
    }
    picked.push(best);
  }
  return picked;
}

function dedupeNear(texts, threshold) {
  const sets = texts.map((t) => new Set(t.toLowerCase().split(/[^a-z0-9]+/).filter(Boolean)));
  const jac = (a, b) => {
    if (a.size === 0 && b.size === 0) return 1;
    let inter = 0;
    for (const w of a) if (b.has(w)) inter++;
    return inter / (a.size + b.size - inter);
  };
  const kept = [];
  sets.forEach((s, i) => {
    if (!kept.some((j) => jac(s, sets[j]) >= threshold)) kept.push(i);
  });
  return kept;
}

