function validateToolCall(text, tools) {
  const isObj = (v) => typeof v === 'object' && v !== null && !Array.isArray(v);
  const has = (o, k) => Object.prototype.hasOwnProperty.call(o, k);
  let p;
  try { p = JSON.parse(String(text).trim()); } catch (e) { return { ok: false, error: 'invalid json' }; }
  if (!isObj(p)) return { ok: false, error: 'not an object' };
  if (typeof p.tool !== 'string') return { ok: false, error: 'missing tool' };
  if (!has(tools, p.tool)) return { ok: false, error: 'unknown tool: ' + p.tool };
  if (!isObj(p.args)) return { ok: false, error: 'args must be an object' };
  const spec = tools[p.tool];
  for (const k of Object.keys(spec)) {
    if (!has(p.args, k)) return { ok: false, error: 'missing arg: ' + k };
    if (typeof p.args[k] !== spec[k]) return { ok: false, error: 'bad type for ' + k + ': expected ' + spec[k] };
  }
  for (const k of Object.keys(p.args)) {
    if (!has(spec, k)) return { ok: false, error: 'unexpected arg: ' + k };
  }
  return { ok: true, tool: p.tool, args: p.args };
}

function parseReact(text) {
  const out = { thought: null, action: null, input: null, final: null };
  const labels = [['Thought:', 'thought'], ['Action Input:', 'input'], ['Action:', 'action'], ['Final Answer:', 'final']];
  for (const raw of text.split('\n')) {
    const line = raw.trim();
    if (line.startsWith('Observation:')) break;
    for (const [label, key] of labels) {
      if (line.startsWith(label)) {
        if (out[key] === null) out[key] = line.slice(label.length).trim();
        break;
      }
    }
  }
  return out;
}

