function runLoop(replies, tools, maxSteps) {
  const has = (o, k) => Object.prototype.hasOwnProperty.call(o, k);
  const observations = [];
  let steps = 0;
  for (const r of replies) {
    if (has(r, 'final')) return { status: 'done', answer: r.final, steps, observations };
    if (steps >= maxSteps) return { status: 'max_steps', answer: null, steps, observations };
    let obs;
    if (!has(tools, r.action)) obs = 'error: unknown tool ' + r.action;
    else if (!has(tools[r.action], r.input)) obs = 'error: no result for ' + r.input;
    else obs = tools[r.action][r.input];
    observations.push(obs);
    steps++;
  }
  return { status: 'out_of_replies', answer: null, steps, observations };
}

