function retryPlan(statuses, maxAttempts, baseMs, capMs) {
  const waits = [];
  for (let i = 0; i < maxAttempts; i++) {
    const s = i < statuses.length ? statuses[i] : 503;
    if (s >= 200 && s < 300) return { result: 'ok', attempts: i + 1, waits };
    if (!(s === 429 || s >= 500)) return { result: 'failed', attempts: i + 1, waits };
    if (i === maxAttempts - 1) return { result: 'gave_up', attempts: i + 1, waits };
    waits.push(Math.min(capMs, baseMs * Math.pow(2, i)));
  }
  return { result: 'gave_up', attempts: 0, waits };
}

