function routeTool(request, rules, fallback) {
  const words = new Set(request.toLowerCase().match(/[a-z0-9]+/g) || []);
  let best = 0;
  let tool = fallback;
  for (const rule of rules) {
    let score = 0;
    for (const k of new Set(rule.keywords)) {
      if (words.has(k)) score++;
    }
    if (score > best) {
      best = score;
      tool = rule.tool;
    }
  }
  return tool;
}

function trimChat(messages, budget) {
  const cost = (m) => m.content.split(/\s+/).filter(Boolean).length + 3;
  let total = 0;
  for (const m of messages) if (m.role === 'system') total += cost(m);
  const keep = new Set();
  for (let i = messages.length - 1; i >= 0; i--) {
    if (messages[i].role === 'system') continue;
    const c = cost(messages[i]);
    if (total + c > budget) break;
    total += c;
    keep.add(i);
  }
  return messages.filter((m, i) => m.role === 'system' || keep.has(i));
}

function findLoop(actions, k) {
  let run = 0;
  for (let i = 0; i < actions.length; i++) {
    const same = i > 0 && actions[i].tool === actions[i - 1].tool && actions[i].input === actions[i - 1].input;
    run = same ? run + 1 : 1;
    if (run >= k) return i;
  }
  return -1;
}

function mergeParallel(calls, results) {
  const byId = new Map();
  for (const r of results) {
    if (!byId.has(r.id)) byId.set(r.id, r);
  }
  return calls.map((c) => {
    const r = byId.get(c.id);
    if (!r) return { id: c.id, tool: c.tool, ok: false, error: 'no result' };
    if ('error' in r) return { id: c.id, tool: c.tool, ok: false, error: r.error };
    return { id: c.id, tool: c.tool, ok: true, output: r.output };
  });
}

function fillTemplate(template, vars) {
  const missing = [];
  const text = template.replace(/\{\{\s*(\w+)\s*\}\}/g, (whole, name) => {
    if (Object.prototype.hasOwnProperty.call(vars, name)) return String(vars[name]);
    if (!missing.includes(name)) missing.push(name);
    return whole;
  });
  return { text, missing };
}

function tokenF1(prediction, reference) {
  const toks = (s) => s.toLowerCase().split(/[^a-z0-9]+/).filter((t) => t !== '');
  const p = toks(prediction);
  const r = toks(reference);
  if (p.length === 0 && r.length === 0) return 1;
  if (p.length === 0 || r.length === 0) return 0;
  const counts = {};
  for (const t of r) counts[t] = (counts[t] || 0) + 1;
  let common = 0;
  for (const t of p) {
    if (counts[t] > 0) { common++; counts[t]--; }
  }
  if (common === 0) return 0;
  const precision = common / p.length;
  const recall = common / r.length;
  const f1 = (2 * precision * recall) / (precision + recall);
  return Math.round(f1 * 10000) / 10000;
}

