function passAtK(n, c, k) {
  if (n - c < k) return 1;
  let prod = 1;
  for (let i = n - c + 1; i <= n; i++) prod *= 1 - k / i;
  return Math.round((1 - prod) * 1000000) / 1000000;
}

function extractJson(text) {
  for (let i = 0; i < text.length; i++) {
    if (text[i] !== '{') continue;
    let depth = 0, inStr = false, esc = false, end = -1;
    for (let j = i; j < text.length; j++) {
      const ch = text[j];
      if (inStr) {
        if (esc) esc = false;
        else if (ch === '\\') esc = true;
        else if (ch === '"') inStr = false;
      } else if (ch === '"') inStr = true;
      else if (ch === '{') depth++;
      else if (ch === '}') { depth--; if (depth === 0) { end = j; break; } }
    }
    if (end === -1) continue;
    try { return JSON.parse(text.slice(i, end + 1)); } catch (e) { /* try next start */ }
  }
  return null;
}

function checkGuardrail(text) {
  const clean = text.toLowerCase().replace(/\s+/g, ' ');
  const phrases = ['ignore previous instructions', 'ignore all previous instructions', 'disregard the system prompt', 'reveal your system prompt'];
  const flags = [];
  if (phrases.some((p) => clean.includes(p))) flags.push('injection');
  if (/[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/i.test(text)) flags.push('email');
  if (/\b\d{3}-\d{3}-\d{4}\b/.test(text)) flags.push('phone');
  if (/\b\d{3}-\d{2}-\d{4}\b/.test(text)) flags.push('ssn');
  return { flags, safe: flags.length === 0 };
}

function parseSSE(text) {
  const lines = text.split('\n').map((l) => (l.endsWith('\r') ? l.slice(0, -1) : l));
  lines.pop();
  const events = [];
  let name = 'message';
  let data = [];
  for (const line of lines) {
    if (line === '') {
      if (data.length > 0) events.push({ event: name, data: data.join('\n') });
      name = 'message';
      data = [];
    } else if (line[0] === ':') {
      continue;
    } else {
      const idx = line.indexOf(':');
      if (idx === -1) continue;
      const field = line.slice(0, idx);
      let value = line.slice(idx + 1);
      if (value[0] === ' ') value = value.slice(1);
      if (field === 'data') data.push(value);
      else if (field === 'event') name = value;
    }
  }
  return events;
}

function macroMetrics(actual, predicted) {
  const n = actual.length;
  if (n === 0) return { accuracy: 0, macroPrecision: 0, macroRecall: 0, macroF1: 0 };
  const labels = [...new Set([...actual, ...predicted])];
  let correct = 0;
  for (let i = 0; i < n; i++) if (actual[i] === predicted[i]) correct++;
  let sp = 0, sr = 0, sf = 0;
  for (const L of labels) {
    let tp = 0, fp = 0, fn = 0;
    for (let i = 0; i < n; i++) {
      if (predicted[i] === L && actual[i] === L) tp++;
      else if (predicted[i] === L) fp++;
      else if (actual[i] === L) fn++;
    }
    const p = tp + fp === 0 ? 0 : tp / (tp + fp);
    const r = tp + fn === 0 ? 0 : tp / (tp + fn);
    const f = p + r === 0 ? 0 : (2 * p * r) / (p + r);
    sp += p; sr += r; sf += f;
  }
  const rd = (x) => Math.round(x * 10000) / 10000;
  return { accuracy: rd(correct / n), macroPrecision: rd(sp / labels.length), macroRecall: rd(sr / labels.length), macroF1: rd(sf / labels.length) };
}

function latencySummary(values) {
  const n = values.length;
  if (n === 0) return { p50: 0, p95: 0, max: 0, mean: 0 };
  const s = values.slice().sort((a, b) => a - b);
  const pct = (p) => s[Math.max(1, Math.ceil((p * n) / 100)) - 1];
  let sum = 0;
  for (const v of s) sum += v;
  return { p50: pct(50), p95: pct(95), max: s[n - 1], mean: Math.round((sum / n) * 100) / 100 };
}
